import { useState } from "react";
import { Container, Row, Col } from "react-bootstrap";
import "./Education.css";


export const Education = () => {
  const education = [
    {
      institute: "Acharya Institute of Technology",
      degree: "Master of Computer Applications (MCA)",
      year: "2025 – 2027",
      status: "Currently Pursuing"
    },
    {
      institute: "KLE Society’s Shri Shivayogi Murughendra Swamiji BCA College",
      degree: "Bachelor of Computer Applications (BCA)",
      year: "2022 – 2025"
    },
    {
      institute: "Sai Niketan PU Science College",
      degree: "PUC – Science",
      year: "2020 – 2022"
    },
    {
      institute: "Swami Vivekanand International Public School (CBSE)",
      degree: "Schooling",
      year: "2009 – 2020"
    }
  ];

  return (
    <section className="education-section" id="education">
      <Container>
        <Row>
          <Col>
            <h2 className="section-title">Education Journey</h2>
            <p className="section-subtitle">
              My academic path shaping me into a future-ready software professional 🚀
            </p>
          </Col>
        </Row>

        <Row className="timeline">
          {education.map((edu, index) => (
            <Col md={6} key={index} className="edu-card">
              <div className="edu-box">
                <h4>{edu.institute}</h4>
                <h6>{edu.degree}</h6>
                <span>{edu.year}</span>
                {edu.status && <p className="status">{edu.status}</p>}
              </div>
            </Col>
          ))}
        </Row>
      </Container>
    </section>
  );
};
